const raw = $input.first().json;

function normalizePhone(phone) {
  if (!phone) return '';
  const d = String(phone).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  if (String(phone).trim().startsWith('+')) return '+' + d;
  return d ? '+1' + d : '';
}
function pick(obj, ...keys) {
  for (const k of keys) {
    if (obj && obj[k] != null && String(obj[k]).trim() !== '') return String(obj[k]).trim();
  }
  return '';
}

let body;
if (raw.data && typeof raw.data === 'object' && !raw.body) {
  const d = raw.data;
  const fullName = pick(d, 'full_name', 'nom_complet', 'fullname');
  const parts = fullName.split(/\s+/).filter(Boolean);
  body = {
    first_name: pick(d, 'first_name', 'prénom', 'prenom') || parts[0] || '',
    last_name: pick(d, 'last_name', 'nom') || parts.slice(1).join(' ') || '',
    phone: pick(d, 'phone_number', 'phone', 'téléphone', 'tel', 'mobile'),
    email: pick(d, 'email', 'courriel'),
    full_address: pick(d, 'street_address', 'address', 'full_address', 'adresse', 'property_address'),
    selling_timeline: pick(d, 'selling_timeline', 'délai_vente', 'timeline', 'when_do_you_plan_to_sell'),
    estimated_value: pick(d, 'estimated_value', 'valeur_estimée', 'property_value'),
    current_mortgage: pick(d, 'current_mortgage', 'hypothèque', 'mortgage_balance'),
    ad_id: raw.ad?.id || '',
    ad_name: raw.ad?.name || '',
    form_id: raw.form?.id || '',
    form_name: raw.form?.name || '',
    meta_lead_id: raw.id || '',
    page_id: raw.page?.id || '964640820063787',
  };
} else {
  body = raw.body || raw;
}

const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const toronto = new Date(nowStr);
const hour = toronto.getHours();
const day = toronto.getDay();
const isBusinessHours = day >= 1 && day <= 6 && hour >= 8 && hour < 20;

return [{
  json: {
    ...body,
    first_name: body.first_name || '',
    last_name: body.last_name || '',
    phone: normalizePhone(body.phone || body.mobile),
    email: body.email || body.email_from || '',
    full_address: body.full_address || body.street || body.address || '',
    selling_timeline: body.selling_timeline || '',
    estimated_value: body.estimated_value || '',
    current_mortgage: body.current_mortgage || '',
    isBusinessHours,
    torontoHour: hour,
    torontoDay: day
  }
}];

const b = $('2 Normaliser lead Meta').first().json;
const token = '{{META_IMMO_WEBHOOK_TOKEN}}';
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/immo/meta-lead',
  headers: { 'X-Immo-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: {
    first_name: b.first_name,
    last_name: b.last_name,
    phone: b.phone,
    email: b.email,
    full_address: b.full_address,
    selling_timeline: b.selling_timeline,
    estimated_value: b.estimated_value,
    current_mortgage: b.current_mortgage,
    ad_id: b.ad_id || '',
    form_id: b.form_id || b.leadgen_form_id || '',
    page_id: b.page_id || '964640820063787',
    meta_lead_id: b.meta_lead_id || b.leadgen_id || b.id || ''
  },
  json: true,
});
return [{ json: { ...b, ...res } }];

const lead = $('3 Odoo Create Lead').first().json;
const prep = $('2 Normaliser lead Meta').first().json;
const phone = prep.phone;
if (!phone) return [{ json: { ...lead, sms_sent: false } }];
try {
  const sid = '{{TWILIO_ACCOUNT_SID}}';
  const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
  const msg = `Bonjour ${prep.first_name || ''}! Merci pour votre demande d'évaluation marchande. Sophie vous appellera sous peu. — Maison Recherchée`;
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
    headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent('{{TWILIO_FROM_IMMO}}')}&Body=${encodeURIComponent(msg)}`,
  });
  return [{ json: { ...lead, sms_sent: true } }];
} catch (e) {
  return [{ json: { ...lead, sms_sent: false, sms_error: String(e.message || e) } }];
}

const lead = $('3 Odoo Create Lead').first().json;
const prep = $('2 Normaliser lead Meta').first().json;
const apiKey = '{{ELEVENLABS_API_KEY}}';
const agentId = lead.agent_id || lead.elevenlabs_agent_id_immo || '';
const phId = lead.elevenlabs_phone_number_id || '';
if (!agentId || !phId || !prep.phone) {
  return [{ json: { ...lead, call_skipped: true, reason: 'missing_agent_or_phone' } }];
}
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.elevenlabs.io/v1/convai/twilio/outbound-call',
    headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
    body: {
      agent_id: agentId,
      agent_phone_number_id: phId,
      to_number: prep.phone,
      telephony_call_config: { ringing_timeout_secs: 25 },
      conversation_initiation_client_data: {
        dynamic_variables: {
          lead_name: prep.first_name || 'there',
          property_address: prep.full_address || '',
          selling_timeline: prep.selling_timeline || '',
          lead_id_odoo: String(lead.lead_id || '')
        }
      }
    },
    json: true,
  });
  return [{ json: { ...lead, ...res, call_started: true } }];
} catch (e) {
  return [{ json: { ...lead, call_skipped: true, call_error: String(e.message || e) } }];
}

const lead = $('3 Odoo Create Lead').first().json;
if (!lead.lead_id) return [{ json: lead }];
const token = '{{META_IMMO_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/immo/lead/update',
  headers: { 'X-Immo-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: { lead_id: lead.lead_id, increment_call_attempt: true },
  json: true,
});
return [{ json: lead }];

const lead = $('3 Odoo Create Lead').first().json;
if (!lead.lead_id) return [{ json: lead }];
const token = '{{META_IMMO_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/immo/lead/update',
  headers: { 'X-Immo-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: {
    lead_id: lead.lead_id,
    next_action: 'Appel matin programmé 9h Toronto (lead hors heures)',
    nurture_step: 0
  },
  json: true,
});
return [{ json: lead }];

